<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Box, Connection, Cpu, House, MapLocation, Plus, Search, Tickets } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import KnowledgeList from './components/KnowledgeList.vue'
import KnowledgeDetail from './components/KnowledgeDetail.vue'
import ProductDetail from './components/ProductDetail.vue'
import RelationDrawer from './components/RelationDrawer.vue'

type User={username:string;displayName:string;role:string;permissions:string[]}
type CenterKey='products'|'software'|'algorithms'|'model-capabilities'|'scenes'|'solutions'
const route=useRoute(),router=useRouter()
const token=ref(localStorage.hzToken||''),user=ref<User|null>(null),loginForm=reactive({username:'',password:''}),loginError=ref('')
const loading=ref(false),loadError=ref(''),rows=ref<any[]>([]),active=ref<any>(null),metrics=ref<Record<string,number>>({}),categories=ref<any[]>([])
const productDialog=ref(false),catalogDialog=ref(false),relationDrawer=ref(false),bomDialog=ref(false),saving=ref(false),editingId=ref<number|null>(null),dialogCenter=ref<CenterKey>('software'),sceneOptions=ref<any[]>([]),bomRows=ref<any[]>([])

const centers=[{key:'products',label:'产品中心',icon:Box,description:'统一沉淀产品、主型号、技术参数与关联知识。',placeholder:'搜索产品名称、主型号或分类'},{key:'software',label:'软件中心',icon:Cpu,description:'统一管理软件平台、版本与适配关系。',placeholder:'搜索软件名称、版本或简介'},{key:'algorithms',label:'算法中心',icon:Connection,description:'统一管理算法版本、类型与业务用途。',placeholder:'搜索算法名称、版本或分类'},{key:'model-capabilities',label:'模型能力中心',icon:Connection,description:'统一管理可复用模型能力、指标与部署要求。',placeholder:'搜索模型能力名称或分类'},{key:'scenes',label:'场景中心',icon:MapLocation,description:'从业务问题出发组织产品、能力与解决方案。',placeholder:'搜索场景名称或业务简介'},{key:'solutions',label:'方案中心',icon:Tickets,description:'沉淀标准方案、场景关系与标准BOM。',placeholder:'搜索方案名称、场景或等级'}] as const
const currentCenter=computed<CenterKey>(()=>String(route.name||'products').replace(/-detail$/,'') as CenterKey)
const currentMeta=computed(()=>centers.find(item=>item.key===currentCenter.value)||centers[0])
const isDetail=computed(()=>String(route.name||'').endsWith('-detail'))
const can=(permission:string)=>user.value?.permissions.includes(permission)||false

const productForm=reactive({name:'',product_type:'HARDWARE',model_code:'',category_id:null as number|null,summary:'',status:'ON_SALE',main_image:''})
const catalogForm=reactive({name:'',summary:'',code:'',version:'v1.0',category:'通用',cover_image:'',pain_points:'',goals:'',business_process:'',core_capability_summary:'',function_type:'识别',input_summary:'',output_summary:'',metrics:'',input_requirements:'',deployment_requirements:'',boundaries:'',software_type:'PLATFORM',vendor:'海智科技',deployment_mode:'PRIVATE',supported_os:[] as string[],scene_id:null as number|null,tier:'标准型',target_description:'',coverage_scope:'',architecture_summary:'',implementation_notes:'',status:'SUPPORTED'})
const blankCatalog={...catalogForm,supported_os:[] as string[]}

async function api(url:string,options:any={}){const response=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(token.value?{Authorization:'Bearer '+token.value}:{}),...(options.headers||{})}});const data=response.status===204?null:await response.json();if(!response.ok)throw Error(data?.detail||'请求失败');return data}
async function signIn(){loginError.value='';try{const data=await api('/api/auth/login',{method:'POST',body:JSON.stringify(loginForm)});token.value=data.access_token;localStorage.hzToken=token.value;user.value=data.user;await router.replace('/products')}catch(error:any){loginError.value=error.message}}
function logout(){localStorage.removeItem('hzToken');token.value='';user.value=null;rows.value=[];active.value=null}
async function loadCategories(){if(!categories.value.length)categories.value=await api('/api/product-categories')}
async function loadRoute(){if(!user.value)return;loading.value=true;loadError.value='';try{if(route.name==='home'){metrics.value=(await api('/api/dashboard')).metrics;rows.value=await api('/api/products');active.value=null;return}if(isDetail.value){const id=Number(route.params.id);if(currentCenter.value==='products')await loadCategories();active.value=await api('/api/'+currentCenter.value+'/'+id);return}active.value=null;rows.value=await api('/api/'+currentCenter.value)}catch(error:any){loadError.value=error.message||'知识数据加载失败'}finally{loading.value=false}}
async function navigate(key:string){await router.push(key==='home'?'/':'/'+key)}
async function openRecord(row:any){await router.push('/'+currentCenter.value+'/'+row.id)}
async function openRelation(relation:any){await router.push('/'+relation.type+'/'+relation.id)}

async function openCreate(){editingId.value=null;if(currentCenter.value==='products'){await loadCategories();Object.assign(productForm,{name:'',product_type:'HARDWARE',model_code:'',category_id:categories.value[0]?.id||null,summary:'',status:'ON_SALE',main_image:''});productDialog.value=true;return}dialogCenter.value=currentCenter.value;Object.assign(catalogForm,blankCatalog,{supported_os:[]});if(dialogCenter.value==='solutions'){sceneOptions.value=await api('/api/scenes');catalogForm.scene_id=sceneOptions.value[0]?.id||null}catalogDialog.value=true}
async function openEdit(row:any=active.value){editingId.value=row.id;if(currentCenter.value==='products'){await loadCategories();Object.assign(productForm,{name:row.name,product_type:row.productType||'HARDWARE',model_code:row.modelCode,category_id:row.categoryId,summary:row.summary,status:row.status,main_image:row.mainImage||''});productDialog.value=true;return}dialogCenter.value=currentCenter.value;Object.assign(catalogForm,blankCatalog,{name:row.name,summary:row.summary||'',code:row.code||'',version:row.version||'v1.0',category:row.category||'通用',cover_image:row.coverImage||'',pain_points:row.painPoints||'',goals:(row.goals||[]).join('\n'),business_process:(row.businessProcess||[]).join('\n'),core_capability_summary:row.coreCapabilitySummary||'',function_type:row.functionType||'识别',input_summary:row.inputSummary||'',output_summary:row.outputSummary||'',metrics:pairsToText(row.metrics),input_requirements:pairsToText(row.inputRequirements),deployment_requirements:pairsToText(row.deploymentRequirements),boundaries:(row.boundaries||[]).join('\n'),software_type:row.softwareType||'PLATFORM',vendor:row.vendor||'海智科技',deployment_mode:row.deploymentMode||'PRIVATE',supported_os:row.supportedOs||[],scene_id:row.sceneId||null,tier:row.tier||'标准型',target_description:row.targetDescription||'',coverage_scope:row.coverageScope||'',architecture_summary:row.architectureSummary||'',implementation_notes:row.implementationNotes||'',status:row.status||'SUPPORTED'});if(dialogCenter.value==='solutions')sceneOptions.value=await api('/api/scenes');catalogDialog.value=true}
const pairsToText=(value:Record<string,any>={})=>Object.entries(value).map(([key,item])=>key+'='+item).join('\n')
const textToPairs=(value:string)=>Object.fromEntries(value.split('\n').map(line=>line.split('=')).filter(parts=>parts[0]?.trim()).map(parts=>[parts[0].trim(),(parts[1]||'').trim()]))
const lines=(value:string)=>value.split('\n').map(item=>item.trim()).filter(Boolean)
async function saveProduct(){if(!productForm.name.trim()||!productForm.model_code.trim()||!productForm.category_id)return ElMessage.warning('请完整填写产品名称、主型号和分类');saving.value=true;try{if(editingId.value){await api('/api/admin/products/'+editingId.value,{method:'PATCH',body:JSON.stringify(productForm)});productDialog.value=false;await loadRoute()}else{const created=await api('/api/admin/products',{method:'POST',body:JSON.stringify(productForm)});productDialog.value=false;await router.push({path:'/products/'+created.id,query:{edit:'1'}})}ElMessage.success(editingId.value?'产品已保存':'产品已创建，请继续完善详情')}finally{saving.value=false}}
async function saveProductDetails(value:any){await api('/api/admin/products/'+active.value.id,{method:'PATCH',body:JSON.stringify(value)});active.value=await api('/api/products/'+active.value.id);await router.replace(route.path);ElMessage.success('产品详情已保存')}
async function saveProductPrice(value:any){await api('/api/products/'+active.value.id+'/prices',{method:'PATCH',body:JSON.stringify(value)});active.value=await api('/api/products/'+active.value.id);ElMessage.success('产品价格已保存')}
async function saveCatalog(){if(!catalogForm.name.trim())return ElMessage.warning('请输入名称');saving.value=true;try{const body:any={...catalogForm};if(['algorithms','model-capabilities'].includes(dialogCenter.value)){body.metrics=textToPairs(body.metrics);body.boundaries=lines(body.boundaries)}if(dialogCenter.value==='model-capabilities'){body.input_requirements=textToPairs(body.input_requirements);body.deployment_requirements=textToPairs(body.deployment_requirements)}if(dialogCenter.value==='scenes'){body.goals=lines(body.goals);body.business_process=lines(body.business_process)}const url='/api/admin/catalog/'+dialogCenter.value+(editingId.value?'/'+editingId.value:'');await api(url,{method:editingId.value?'PATCH':'POST',body:JSON.stringify(body)});catalogDialog.value=false;await loadRoute();ElMessage.success('知识条目已保存')}finally{saving.value=false}}
async function deleteRecord(row:any=active.value){await ElMessageBox.confirm('删除后不可恢复，确认继续？','删除知识条目',{type:'warning'});if(currentCenter.value==='products')await api('/api/admin/products/'+row.id,{method:'DELETE'});else await api('/api/admin/catalog/'+currentCenter.value+'/'+row.id,{method:'DELETE'});ElMessage.success('知识条目已删除');await router.push('/'+currentCenter.value)}

async function loadRelationOptions(kind:string){return api('/api/'+kind)}
async function addRelation(payload:any){await api('/api/relations',{method:'POST',body:JSON.stringify(payload)});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);relationDrawer.value=false;ElMessage.success('关联已建立')}
async function removeRelation(relation:any){await ElMessageBox.confirm('确认移除该知识关联？','移除关联',{type:'warning'});await api('/api/relations/'+relation.relationId,{method:'DELETE'});active.value=await api('/api/'+currentCenter.value+'/'+active.value.id);ElMessage.success('关联已移除')}
async function openBom(){rows.value=await api('/api/products');bomRows.value=(active.value.bom?.items||[]).map((item:any)=>({product_id:item.productId,quantity:item.quantity,unit:item.unit,purpose:item.purpose,requirement_level:item.requirementLevel,recommendation_reason:item.recommendationReason}));bomDialog.value=true}
function addBom(){bomRows.value.push({product_id:rows.value[0]?.id||null,quantity:1,unit:'台',purpose:'',requirement_level:'REQUIRED',recommendation_reason:''})}
async function saveBom(){saving.value=true;try{await api('/api/solutions/'+active.value.id+'/bom',{method:'PATCH',body:JSON.stringify({items:bomRows.value})});active.value=await api('/api/solutions/'+active.value.id);bomDialog.value=false;ElMessage.success('标准BOM已保存')}finally{saving.value=false}}

watch(()=>route.fullPath,loadRoute)
onMounted(async()=>{if(token.value){try{user.value=await api('/api/auth/me');if(!can('KNOWLEDGE_VIEW'))throw Error('当前账号没有知识查看权限');await loadRoute()}catch{logout()}}})
</script>

<template>
 <main v-if="!token" class="login"><section class="login-card"><div class="brand"><div class="brand-mark">海</div><b>海智产品中心</b></div><h1>六大知识中心</h1><p>产品、软件、算法、模型能力、场景与方案的一体化知识平台</p><el-alert v-if="loginError" :title="loginError" type="error" :closable="false" show-icon/><el-form label-position="top" @submit.prevent="signIn"><el-form-item label="账号"><el-input v-model="loginForm.username" autocomplete="username"/></el-form-item><el-form-item label="密码"><el-input v-model="loginForm.password" type="password" show-password autocomplete="current-password"/></el-form-item><el-button type="primary" native-type="submit" @click="signIn">登录</el-button></el-form></section></main>
 <main v-else class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">海</div><b>海智产品中心</b></div><div class="nav-title">知识中心</div><el-menu :default-active="currentCenter" @select="navigate"><el-menu-item index="home"><el-icon><House/></el-icon><span>工作台</span></el-menu-item><el-menu-item v-for="center in centers" :key="center.key" :index="center.key"><el-icon><component :is="center.icon"/></el-icon><span>{{center.label}}</span></el-menu-item></el-menu></aside>
  <section class="workspace"><header class="header"><div><b>{{isDetail?'知识详情':currentMeta.label}}</b><span>六大知识中心</span></div><div class="user"><el-avatar>{{user?.displayName.slice(0,1)}}</el-avatar><span><b>{{user?.displayName}}</b><small>{{can('KNOWLEDGE_MANAGE')?'产品经理':'只读用户'}}</small></span><el-button text @click="logout">退出</el-button></div></header><div class="content">
   <template v-if="route.name==='home'"><div class="page-head"><div><h1>知识工作台</h1><p>从六大知识中心快速进入产品知识与方案协作。</p></div><el-button v-if="can('KNOWLEDGE_MANAGE')" type="primary" :icon="Plus" @click="router.push('/products').then(openCreate)">新增产品</el-button></div><div class="metric-grid"><button v-for="center in centers" :key="center.key" class="metric card" @click="navigate(center.key)"><span class="value">{{metrics[center.key==='model-capabilities'?'capabilities':center.key]||0}}</span><span class="label">{{center.label}}</span></button></div><h2 class="section-title">最近产品</h2><div class="product-grid"><article v-for="item in rows.slice(0,6)" :key="item.id" class="card product-card" @click="router.push('/products/'+item.id)"><div class="product-icon"><el-icon><Box/></el-icon></div><h3>{{item.name}}</h3><p>{{item.summary}}</p><span class="status">{{item.modelCode}}</span></article></div></template>
   <KnowledgeList v-else-if="!isDetail" :title="currentMeta.label" :description="currentMeta.description" :search-placeholder="currentMeta.placeholder" :rows="rows" :loading="loading" :error="loadError" :can-manage="can('KNOWLEDGE_MANAGE')" @create="openCreate" @open="openRecord" @edit="openEdit" @delete="deleteRecord" @retry="loadRoute"/>
   <ProductDetail v-else-if="currentCenter==='products'&&active" :record="active" :categories="categories" :can-manage="can('KNOWLEDGE_MANAGE')" :show-price="can('PRICE_VIEW')" :start-editing="route.query.edit==='1'" @back="router.push('/products')" @save="saveProductDetails" @save-price="saveProductPrice" @delete="deleteRecord" @relate="relationDrawer=true" @open-relation="openRelation"/>
   <KnowledgeDetail v-else :center-title="currentMeta.label" :record="active" :loading="loading" :error="loadError" :can-manage="can('KNOWLEDGE_MANAGE')" :show-price="can('PRICE_VIEW')&&currentCenter==='solutions'" @back="router.push('/'+currentCenter)" @edit="openEdit" @delete="deleteRecord" @relate="relationDrawer=true" @edit-bom="openBom" @retry="loadRoute" @open-relation="openRelation"/>
  </div></section>
 </main>

 <RelationDrawer v-if="active" v-model="relationDrawer" :source-type="currentCenter" :source-id="active.id" :relations="active.relations||[]" :load-options="loadRelationOptions" @add="addRelation" @remove="removeRelation"/>
 <el-dialog v-model="productDialog" :title="editingId?'编辑产品':'新增产品'" width="600px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="产品名称" required><el-input v-model="productForm.name"/></el-form-item><el-form-item label="产品类型" required><el-select v-model="productForm.product_type"><el-option label="硬件产品" value="HARDWARE"/><el-option label="软件产品" value="SOFTWARE_PRODUCT"/><el-option label="算法/模型商业产品" value="AI_PRODUCT"/><el-option label="系统/解决方案产品" value="SYSTEM_SOLUTION"/><el-option label="配套设备" value="ACCESSORY"/></el-select></el-form-item><el-form-item label="主型号" required><el-input v-model="productForm.model_code"/></el-form-item><el-form-item label="分类" required><el-select v-model="productForm.category_id"><el-option v-for="item in categories" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="销售状态"><el-select v-model="productForm.status"><el-option label="在售" value="ON_SALE"/><el-option label="停售" value="OFF_SALE"/></el-select></el-form-item><el-form-item label="主图"><el-input v-model="productForm.main_image" placeholder="输入图片地址"/></el-form-item><el-form-item label="一句话简介" class="dialog-span"><el-input v-model="productForm.summary" type="textarea" :rows="3"/></el-form-item></div></el-form><template #footer><el-button @click="productDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveProduct">{{editingId?'保存':'创建并完善详情'}}</el-button></template></el-dialog>

 <el-dialog v-model="catalogDialog" :title="editingId?'编辑知识条目':'新增知识条目'" width="660px"><el-form label-position="top"><div class="dialog-grid"><el-form-item label="名称" required><el-input v-model="catalogForm.name"/></el-form-item><el-form-item v-if="['software','algorithms','model-capabilities','solutions'].includes(dialogCenter)" label="编码"><el-input v-model="catalogForm.code"/></el-form-item><el-form-item v-if="['software','algorithms','model-capabilities'].includes(dialogCenter)" label="当前版本"><el-input v-model="catalogForm.version"/></el-form-item><el-form-item v-if="['algorithms','model-capabilities','scenes','solutions'].includes(dialogCenter)" label="分类"><el-input v-model="catalogForm.category"/></el-form-item><template v-if="dialogCenter==='software'"><el-form-item label="软件类型"><el-select v-model="catalogForm.software_type"><el-option label="平台软件" value="PLATFORM"/><el-option label="客户端软件" value="CLIENT"/><el-option label="服务组件" value="SERVICE"/></el-select></el-form-item><el-form-item label="厂商"><el-input v-model="catalogForm.vendor"/></el-form-item><el-form-item label="部署方式"><el-select v-model="catalogForm.deployment_mode"><el-option label="私有化部署" value="PRIVATE"/><el-option label="云端部署" value="CLOUD"/><el-option label="混合部署" value="HYBRID"/></el-select></el-form-item><el-form-item label="支持操作系统" class="dialog-span"><el-select v-model="catalogForm.supported_os" multiple allow-create filterable><el-option label="Linux" value="Linux"/><el-option label="Windows" value="Windows"/><el-option label="国产操作系统" value="国产操作系统"/></el-select></el-form-item></template><template v-if="dialogCenter==='algorithms'"><el-form-item label="输入摘要" class="dialog-span"><el-input v-model="catalogForm.input_summary" type="textarea"/></el-form-item><el-form-item label="输出摘要" class="dialog-span"><el-input v-model="catalogForm.output_summary" type="textarea"/></el-form-item></template><template v-if="['algorithms','model-capabilities'].includes(dialogCenter)"><el-form-item v-if="dialogCenter==='model-capabilities'" label="功能类型"><el-select v-model="catalogForm.function_type"><el-option v-for="item in ['识别','检测','跟踪','融合','预测','分析']" :key="item" :label="item" :value="item"/></el-select></el-form-item><el-form-item label="核心指标"><el-input v-model="catalogForm.metrics" type="textarea" placeholder="每行：名称=值"/></el-form-item><el-form-item v-if="dialogCenter==='model-capabilities'" label="输入要求"><el-input v-model="catalogForm.input_requirements" type="textarea" placeholder="每行：名称=值"/></el-form-item><el-form-item v-if="dialogCenter==='model-capabilities'" label="部署要求"><el-input v-model="catalogForm.deployment_requirements" type="textarea" placeholder="每行：名称=值"/></el-form-item><el-form-item label="适用边界"><el-input v-model="catalogForm.boundaries" type="textarea" placeholder="每行一项"/></el-form-item></template><template v-if="dialogCenter==='scenes'"><el-form-item label="封面图"><el-input v-model="catalogForm.cover_image"/></el-form-item><el-form-item label="业务痛点" class="dialog-span"><el-input v-model="catalogForm.pain_points" type="textarea"/></el-form-item><el-form-item label="建设目标"><el-input v-model="catalogForm.goals" type="textarea" placeholder="每行一项"/></el-form-item><el-form-item label="业务流程"><el-input v-model="catalogForm.business_process" type="textarea" placeholder="每行一步"/></el-form-item><el-form-item label="核心模型能力" class="dialog-span"><el-input v-model="catalogForm.core_capability_summary" type="textarea"/></el-form-item></template><template v-if="dialogCenter==='solutions'"><el-form-item label="关联场景"><el-select v-model="catalogForm.scene_id"><el-option v-for="item in sceneOptions" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="方案等级"><el-input v-model="catalogForm.tier"/></el-form-item><el-form-item label="方案目标" class="dialog-span"><el-input v-model="catalogForm.target_description" type="textarea"/></el-form-item><el-form-item label="覆盖范围" class="dialog-span"><el-input v-model="catalogForm.coverage_scope" type="textarea"/></el-form-item><el-form-item label="方案架构" class="dialog-span"><el-input v-model="catalogForm.architecture_summary" type="textarea"/></el-form-item><el-form-item label="实施说明" class="dialog-span"><el-input v-model="catalogForm.implementation_notes" type="textarea"/></el-form-item></template><el-form-item label="状态"><el-select v-model="catalogForm.status"><el-option label="正式支持" value="SUPPORTED"/><el-option label="Beta" value="BETA"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item label="一句话简介" class="dialog-span"><el-input v-model="catalogForm.summary" type="textarea" :rows="3"/></el-form-item></div></el-form><template #footer><el-button @click="catalogDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCatalog">保存</el-button></template></el-dialog>

 <el-dialog v-model="bomDialog" title="编辑标准BOM" width="920px"><div class="bom-editor-actions"><span>引用产品中心中的真实产品与主型号。</span><el-button :icon="Plus" @click="addBom">添加产品</el-button></div><el-table :data="bomRows" border><el-table-column label="产品" min-width="190"><template #default="scope"><el-select v-model="scope.row.product_id" filterable><el-option v-for="item in rows" :key="item.id" :label="item.name+' · '+item.modelCode" :value="item.id"/></el-select></template></el-table-column><el-table-column label="数量" width="110"><template #default="scope"><el-input-number v-model="scope.row.quantity" :min="1"/></template></el-table-column><el-table-column label="单位" width="80"><template #default="scope"><el-input v-model="scope.row.unit"/></template></el-table-column><el-table-column label="用途" min-width="130"><template #default="scope"><el-input v-model="scope.row.purpose"/></template></el-table-column><el-table-column label="要求" width="110"><template #default="scope"><el-select v-model="scope.row.requirement_level"><el-option label="必选" value="REQUIRED"/><el-option label="推荐" value="RECOMMENDED"/><el-option label="可选" value="OPTIONAL"/></el-select></template></el-table-column><el-table-column label="推荐理由" min-width="150"><template #default="scope"><el-input v-model="scope.row.recommendation_reason"/></template></el-table-column><el-table-column width="54"><template #default="scope"><el-button link type="danger" @click="bomRows.splice(scope.$index,1)">删除</el-button></template></el-table-column></el-table><template #footer><el-button @click="bomDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveBom">保存BOM</el-button></template></el-dialog>
